	SELECT
	'RECR'||
	LPAD(NVL(TO_NUMBER(SUBSTR(MAX(RECRUITMENT_NO),
	LENGTH('RECR' ) + 1)), 0) + 1, 6, '0')
	FROM RECRUITMENT_NOTICE

